function makeImgUrl(seed, w = 800) {
    const id = UNSPLASH_IDS[hashString(seed) % UNSPLASH_IDS.length];
    return `https://images.unsplash.com/photo-${id}?fm=webp&w=${w}&q=60`;
}

const DEST_TYPES = {
    beach: 'beach', mountain: 'mountain', heritage: 'heritage', spiritual: 'spiritual',
    adventure: 'adventure', nature: 'nature', wildlife: 'wildlife', hill_station: 'hill_station',
    city: 'city', desert: 'desert', island: 'island', backwater: 'backwater',
    lake: 'lake', historical: 'historical', pilgrimage: 'pilgrimage'
};

function makeIntro(name, state, type, highlights) {
    const phrases = [
        `When travelers search for must visit places in ${name}, they discover a destination that truly rewards curiosity.`,
        `The best places to visit in ${name} span from ${highlights[0]} to ${highlights[1]}.`,
        `As one of the top tourist attractions in ${name}, each spot tells a unique story of ${state}'s rich heritage.`,
        `Whether you are looking for things to do in ${name} over a weekend or planning a longer escape, this travel guide to ${name} covers every must-see experience.`,
        `From iconic landmarks to hidden corners, these curated picks ensure you experience the very best of ${name}.`
    ];
    return phrases.join(' ');
}

function makeImagePrompt(attraction, destination) {
    return `Ultra realistic travel photography, golden hour lighting, vibrant colors, ${attraction} in ${destination}, tourists enjoying the view, DSLR quality, 4k, cinematic composition, highly detailed`;
}

function createAttraction(name, desc, why, time, duration, maps, category, dest) {
    return {
        name,
        description: desc,
        whyVisit: why,
        bestTime: time,
        duration,
        mapsSearch: maps,
        category,
        imagePrompt: makeImagePrompt(name, dest),
        slug: slugify(name),
        coverImage: makeImgUrl(`${dest}-${name}`, 800)
    };
}

