// Helper to create destination entries more efficiently
function addDest(name, state, tagline, categories, highlights, attractionsData) {
    const attractions = attractionsData.map((a, i) => ({
        name: a[0],
        description: a[1],
        whyVisit: a[2],
        bestTime: a[3],
        duration: a[4],
        mapsSearch: a[5],
        category: a[6],
        imagePrompt: makeImagePrompt(a[0], name),
        slug: slugify(a[0]),
        coverImage: makeImgUrl(`${name}-${a[0]}`, 800)
    }));
    destinations.push({
        slug: slugify(name), name, state, tagline, categories,
        intro: makeIntro(name, state, categories[0], highlights),
        attractions
    });
}


